662	impl SimScheduler {
663	    /// `None` without a configured prefix cache: the contract reserves a
664	    /// counter set for engines that have one, and a sim that pretends to look
665	    /// nothing up must not publish zeros as if it did.
666	    fn prefix_cache_counters(&self) -> Option<PrefixCacheCounters> {
667	        self.config
668	            .prefix_cache
669	            .map(|_| self.prefix_cache.counters())
670	    }
671	
672	    fn step_legacy(&mut self, ledger: &mut RequestLedger) -> Result<()> {
673	        for QueuedRequest { id, request } in self.queued.drain(..) {
674	            if ledger.is_aborted(id) {
675	                ledger.retire(id);
676	                continue;
677	            }
678	            // The pretend lookup happens exactly where a real engine would do
679	            // it: once, on admission.
680	            self.prefix_cache.note(self.config.prefix_cache, &request);
681	            let prompt_len = request.prompt_tokens.len();
682	            let (pending, finish_reason) =
683	                planned_completion(&self.config, &request.prompt_tokens, request.max_tokens);
684	            ledger.admit(id);
685	            if let Some(top_k) = request.prompt_logprobs {
686	                ledger.echo_prompt(id, logprobs::prompt(&request.prompt_tokens, top_k));
687	            }
688	            if pending.is_empty() {
689	                ledger.finish(id, finish_reason);
690	                continue;
691	            }
692	            self.running.push(RunningRequest {
693	                id,
694	                pending,
695	                next_token_at: Instant::now() + self.config.ttft(prompt_len)?,
696	                finish_reason,
697	                logprobs: request.logprobs,
698	            });
699	        }
700	
701	        let now = Instant::now();
702	        let mut still_running = Vec::new();
703	        for mut running in self.running.drain(..) {
704	            if ledger.is_aborted(running.id) {
705	                ledger.retire(running.id);
706	                continue;
707	            }
708	            if now < running.next_token_at {
709	                still_running.push(running);
710	                continue;
711	            }
712	            let Some(token) = running.pending.pop() else {
713	                ledger.finish(running.id, running.finish_reason);
714	                continue;
715	            };
716	            let logprob = running
717	                .logprobs
718	                .map(|top_k| logprobs::completion(token, top_k));
719	            let logprobs = match logprob {
720	                Some(lp) => vec![Some(lp)],
721	                None => Vec::new(),
722	            };
723	            // Every decode step of a drafted engine is one verify step.
724	            if let (Some(counters), Some((k, accepted))) =
725	                (self.spec_decode.as_mut(), self.config.spec_decode)
726	            {
727	                counters.observe_draft(k, accepted);
728	            }
729	            ledger.push_tokens(running.id, &[token], &logprobs);
730	            if running.pending.is_empty() {
731	                ledger.finish(running.id, running.finish_reason);
732	            } else {
733	                running.next_token_at = Instant::now() + self.config.tpot()?;
734	                still_running.push(running);
735	            }
736	        }
737	        self.running = still_running;
738	        self.park_if_waiting();
739	        Ok(())
740	    }
741	}
742	/// Remaining tokens (reversed) plus the terminal reason. Empty pending means
743	/// finish immediately after admit.
744	fn planned_completion(
745	    config: &SimulatedEngineConfig,
746	    prompt_tokens: &[u32],
747	    max_tokens: usize,
748	) -> (Vec<u32>, FinishReason) {
749	    let script = &config.scripted_completion;
750	    let emit_count = if script.is_empty() {
751	        max_tokens
752	    } else {
753	        max_tokens.min(script.len())
754	    };
755	    let finish_reason = if !script.is_empty() && emit_count == script.len() {
756	        FinishReason::Stop
757	    } else {
758	        FinishReason::Length
759	    };
760	    let mut pending: Vec<u32> = if script.is_empty() {
761	        (0..emit_count)
762	            .map(|index| fake_token_id(prompt_tokens, index, config.fallback_token_id))
763	            .collect()
764	    } else {
765	        script[..emit_count].to_vec()
766	    };
767	    pending.reverse();
768	    (pending, finish_reason)
769	}
