1	//! Wiring between one frontend and one scheduler, plus the engine bundle a
2	//! model line hands back from `launch`.
3	//!
4	//! Both ends of a scheduler are minted together by [`scheduler_pair`], so a
5	//! model crate cannot cross-wire or forget a line: the scheduler side arrives
6	//! as one [`SchedulerBackend`] value, the frontend side as one
7	//! [`SchedulerHandle`]. Channel choices per direction: the submit channel is
8	//! crossbeam (sync consumer on the scheduler thread; senders never block on
9	//! unbounded channels), the step stream is tokio (async consumer in the
10	//! protocol stack; the sync producer's send never blocks either), metrics are
11	//! a shared cell, with changes signaled on the step stream (see
12	//! [`super::StepOutputs`]).
13	//!
14	//! How many schedulers an engine runs and what each one means (DP replicas,
15	//! anything else) is the model line's decision; the contract carries the
16	//! collection and attaches no rank semantics to it. Placement across
17	//! schedulers is frontend policy.
18	
19	use std::sync::Arc;
20	use std::sync::Mutex;
21	use std::sync::atomic::AtomicBool;
22	use std::sync::atomic::AtomicU64;
23	use std::sync::atomic::Ordering;
24	use std::time::Instant;
25	
26	use tokio_util::sync::CancellationToken;
27	use tokio_util::sync::DropGuard;
28	use tokio_util::sync::WaitForCancellationFuture;
29	
30	use super::control::LoraClient;
31	use super::kv::KvCapacity;
32	use super::ledger::RequestLedger;
33	use super::metrics::SchedulerMetrics;
34	use super::request_lifecycle::RequestControl;
35	use super::request_lifecycle::RequestEnvelope;
36	use super::request_lifecycle::StepReceiver;
37	use super::step::Request;
38	use super::step::RequestId;
39	
40	/// Everything the scheduler thread consumes and produces. The driver
41	/// ([`super::drive`]) destructures this; model code only ever sees the
42	/// ledger, through the `step` argument.
43	pub struct SchedulerBackend {
44	    pub(crate) submissions: crossbeam_channel::Receiver<RequestEnvelope>,
45	    pub(crate) ledger: RequestLedger,
46	    pub(crate) metrics: MetricsPublisher,
47	    /// Resolves [`SchedulerHandle::exited`] when dropped.
48	    pub(crate) exit_guard: DropGuard,
49	}
50	
51	/// Sole writer of a scheduler's metrics cell; the driver publishes once per
52	/// iteration from [`super::Scheduler::metrics`].
